package android.os;public class Handler{public static boolean queued;public static final java.util.List<Runnable> tasks=new java.util.ArrayList<>();public Handler(Looper l){}public boolean post(Runnable r){if(queued)tasks.add(r);else execute(r);return true;}static void execute(Runnable r){boolean before=Looper.onMain;Looper.onMain=true;try{r.run();}finally{Looper.onMain=before;}}public static void drain(){while(!tasks.isEmpty())execute(tasks.remove(0));}}
